	ClipperLib.Clear = function (a)
	{
		a.length = 0;
	};

	//ClipperLib.MaxSteps = 64; // How many steps at maximum in arc in BuildArc() function
	ClipperLib.PI = 3.141592653589793;
	ClipperLib.PI2 = 2 * 3.141592653589793;
	/**
	* @constructor
	*/
	ClipperLib.FPoint = function ()
	{
		var a = arguments,
			alen = a.length;
		this.x = 0;
		this.y = 0;
		if (ClipperLib.use_xyz)
		{
			this.z = 0;
			if (alen === 3) // public FPoint(cInt x, cInt y, cInt z = 0)
			{
				this.x = a[0];
				this.y = a[1];
				this.z = a[2];
			}
			else if (alen === 2) // public FPoint(cInt x, cInt y)
			{
				this.x = a[0];
				this.y = a[1];
				this.z = 0;
			}
			else if (alen === 1)
			{
				if (a[0] instanceof ClipperLib.FPoint) // public FPoint(FPoint dp)
				{
					var dp = a[0];
					this.x = dp.x;
					this.y = dp.y;
					this.z = 0;
				}
				else // public FPoint(FPoint pt)
				{
					var pt = a[0];
					if (typeof (pt.z) === "undefined") pt.z = 0;
					this.x = pt.x;
					this.y = pt.y;
					this.z = pt.z;
				}
			}
			else // public FPoint()
			{
				this.x = 0;
				this.y = 0;
				this.z = 0;
			}
		}
		else // if (!ClipperLib.use_xyz)
		{
			if (alen === 2) // public FPoint(cInt X, cInt Y)
			{
				this.x = a[0];
				this.y = a[1];
			}
			else if (alen === 1)
			{
				if (a[0] instanceof ClipperLib.FPoint) // public FPoint(FPoint dp)
				{
					var dp = a[0];
					this.x = dp.x;
					this.y = dp.y;
				}
				else // public FPoint(FPoint pt)
				{
					var pt = a[0];
					this.x = pt.x;
					this.y = pt.y;
				}
			}
			else // public FPoint(FPoint pt)
			{
				this.x = 0;
				this.y = 0;
			}
		}
	};

	ClipperLib.FPoint.op_Equality = function (a, b)
	{
		//return a == b;
		return a.x === b.x && a.y === b.y;
	};

	ClipperLib.FPoint.op_Inequality = function (a, b)
	{
		//return a !== b;
		return a.x !== b.x || a.y !== b.y;
	};

