	ClipperLib.FPoint1 = function (pt)
	{
		this.x = pt.x;
		this.y = pt.y;
		if (ClipperLib.use_xyz)
		{
			if (typeof pt.z === "undefined") this.z = 0;
			else this.z = pt.z;
		}
	};

	ClipperLib.FPoint1.prototype = ClipperLib.FPoint.prototype;

