	'top-center':    [0.5, 0  ],
	'top-right':     [1,   0  ],
	'middle-left':   [0,   0.5],
	'middle-center': [0.5, 0.5],
	'middle-right':  [1,   0.5],
	'bottom-left':   [0,   1  ],
	'bottom-center': [0.5, 1  ],
	'bottom-right':  [1,   1  ]
